-- Schema v1, dumped from commit 667c5a7 ("based on ADR phase 1 done").
--
-- The fixture a migration test builds its "old database" from. Generated by
-- opening the v1 code's database and reading `sqlite_master`, so it is the
-- exact DDL that shipped in v1 rather than a hand-transcribed approximation.
--
-- Never edit this file to match a schema change. A new version means a new
-- fixture; this one has to keep describing v1 forever, or the test stops
-- testing the migration it claims to.

CREATE TABLE "block_templates" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "session_template_id" TEXT NOT NULL REFERENCES session_templates (id) ON DELETE CASCADE, "kind" TEXT NOT NULL, "title" TEXT NOT NULL, "order_index" INTEGER NOT NULL, "target_minutes" INTEGER NULL, "notes" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "check_ins" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "program_id" TEXT NULL REFERENCES programs (id) ON DELETE SET NULL, "phase_id" TEXT NULL REFERENCES phases (id) ON DELETE SET NULL, "date" TEXT NOT NULL, "weight_kg" REAL NULL, "waist_cm" REAL NULL, "extra" TEXT NOT NULL DEFAULT '{}', "photo_refs" TEXT NOT NULL DEFAULT '[]', "notes" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "exercise_templates" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "block_template_id" TEXT NOT NULL REFERENCES block_templates (id) ON DELETE CASCADE, "exercise_id" TEXT NOT NULL REFERENCES exercises (id) ON DELETE RESTRICT, "order_index" INTEGER NOT NULL, "target_sets" INTEGER NOT NULL, "target_reps_min" INTEGER NULL, "target_reps_max" INTEGER NULL, "target_load_kg" REAL NULL, "target_load_text" TEXT NULL, "target_rpe" REAL NULL, "rest_seconds" INTEGER NOT NULL DEFAULT 90, "per_side" INTEGER NOT NULL DEFAULT 0 CHECK ("per_side" IN (0, 1)), "tempo" TEXT NULL, "progression_rule" TEXT NULL, "notes" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "exercises" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "name_key" TEXT NULL, "custom_name" TEXT NULL, "aliases" TEXT NOT NULL DEFAULT '[]', "pattern" TEXT NOT NULL, "load_type" TEXT NOT NULL, "is_unilateral" INTEGER NOT NULL DEFAULT 0 CHECK ("is_unilateral" IN (0, 1)), "primary_muscles" TEXT NOT NULL DEFAULT '[]', "is_system" INTEGER NOT NULL DEFAULT 0 CHECK ("is_system" IN (0, 1)), PRIMARY KEY ("id"), CHECK ((name_key IS NOT NULL) <> (custom_name IS NOT NULL)));
CREATE TABLE "metric_definitions" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "key" TEXT NOT NULL, "label_key" TEXT NOT NULL, "unit" TEXT NULL, "input_type" TEXT NOT NULL, "is_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("is_enabled" IN (0, 1)), "order_index" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "phases" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "program_id" TEXT NOT NULL REFERENCES programs (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "order_index" INTEGER NOT NULL, "start_week" INTEGER NOT NULL, "end_week" INTEGER NOT NULL, "target_session_minutes" INTEGER NULL, "rpe_low" REAL NULL, "rpe_high" REAL NULL, "check_in_due_at_end" INTEGER NOT NULL DEFAULT 1 CHECK ("check_in_due_at_end" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "programs" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "name" TEXT NOT NULL, "start_date" TEXT NOT NULL, "end_date" TEXT NULL, "is_active" INTEGER NOT NULL DEFAULT 0 CHECK ("is_active" IN (0, 1)), "notes" TEXT NULL, "schedule_pattern" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "prs" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "exercise_id" TEXT NOT NULL REFERENCES exercises (id) ON DELETE RESTRICT, "metric" TEXT NOT NULL, "value" REAL NOT NULL, "achieved_at" TEXT NOT NULL, "set_log_id" TEXT NOT NULL REFERENCES set_logs (id) ON DELETE CASCADE, PRIMARY KEY ("id"));
CREATE TABLE "scheduled_sessions" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "program_id" TEXT NOT NULL REFERENCES programs (id) ON DELETE CASCADE, "session_template_id" TEXT NULL REFERENCES session_templates (id) ON DELETE SET NULL, "date" TEXT NOT NULL, "week_number" INTEGER NOT NULL, "kind" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'upcoming', "planned_duration_min" INTEGER NULL, "override_reason" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "session_logs" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "scheduled_session_id" TEXT NOT NULL REFERENCES scheduled_sessions (id) ON DELETE CASCADE, "started_at" TEXT NOT NULL, "ended_at" TEXT NULL, "session_rpe" REAL NULL, "energy" INTEGER NULL, "notes" TEXT NULL, "bodyweight_at_time_kg" REAL NULL, PRIMARY KEY ("id"));
CREATE TABLE "session_templates" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "phase_id" TEXT NOT NULL REFERENCES phases (id) ON DELETE CASCADE, "code" TEXT NOT NULL, "title" TEXT NOT NULL, "day_of_week" INTEGER NULL, "estimated_minutes" INTEGER NULL, "order_index" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "set_logs" ("id" TEXT NOT NULL, "owner_id" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT NULL, "sync_state" TEXT NOT NULL DEFAULT 'pendingCreate', "schema_version" INTEGER NOT NULL DEFAULT 1, "session_log_id" TEXT NOT NULL REFERENCES session_logs (id) ON DELETE CASCADE, "exercise_template_id" TEXT NULL REFERENCES exercise_templates (id) ON DELETE SET NULL, "exercise_id" TEXT NOT NULL REFERENCES exercises (id) ON DELETE RESTRICT, "set_index" INTEGER NOT NULL, "side" TEXT NOT NULL DEFAULT 'both', "status" TEXT NOT NULL DEFAULT 'done', "reps" INTEGER NULL, "weight_kg" REAL NULL, "duration_sec" INTEGER NULL, "distance_m" REAL NULL, "rpe" REAL NULL, "is_pr" INTEGER NOT NULL DEFAULT 0 CHECK ("is_pr" IN (0, 1)), "skip_reason" TEXT NULL, "substituted_for_exercise_id" TEXT NULL REFERENCES exercises (id) ON DELETE RESTRICT, "note" TEXT NULL, PRIMARY KEY ("id"), CHECK ((status = 'skipped') = (skip_reason IS NOT NULL)));
CREATE TABLE "sync_outbox" ("id" TEXT NOT NULL, "table_name" TEXT NOT NULL, "row_id" TEXT NOT NULL, "op" TEXT NOT NULL, "payload" TEXT NOT NULL, "attempt_count" INTEGER NOT NULL DEFAULT 0, "last_error" TEXT NULL, "created_at" TEXT NOT NULL, "next_attempt_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_block_templates_session ON block_templates (session_template_id, order_index);
CREATE INDEX idx_check_ins_date ON check_ins (date);
CREATE INDEX idx_exercise_templates_block ON exercise_templates (block_template_id, order_index);
CREATE INDEX idx_exercise_templates_exercise ON exercise_templates (exercise_id);
CREATE INDEX idx_exercises_owner_deleted ON exercises (owner_id, deleted_at);
CREATE INDEX idx_exercises_owner_updated ON exercises (owner_id, updated_at);
CREATE INDEX idx_metric_definitions_order ON metric_definitions (order_index);
CREATE INDEX idx_phases_program ON phases (program_id, order_index);
CREATE INDEX idx_programs_owner_deleted ON programs (owner_id, deleted_at);
CREATE INDEX idx_programs_owner_updated ON programs (owner_id, updated_at);
CREATE INDEX idx_prs_exercise_metric ON prs (exercise_id, metric);
CREATE INDEX idx_scheduled_sessions_date ON scheduled_sessions (date);
CREATE INDEX idx_scheduled_sessions_program_week ON scheduled_sessions (program_id, week_number);
CREATE INDEX idx_session_logs_scheduled ON session_logs (scheduled_session_id);
CREATE INDEX idx_session_logs_started ON session_logs (started_at);
CREATE INDEX idx_session_templates_phase ON session_templates (phase_id, order_index);
CREATE INDEX idx_set_logs_owner_exercise_created ON set_logs (owner_id, exercise_id, created_at);
CREATE INDEX idx_set_logs_session ON set_logs (session_log_id, set_index);
CREATE INDEX idx_sync_outbox_created ON sync_outbox (created_at);
